#pragma once

#include <QAbstractListModel>
#include <QList>
#include <QString>

struct Task {
    QString title;
    bool done = false;
};

class TaskListModel : public QAbstractListModel
{
    Q_OBJECT
public:
    enum Role { TitleRole = Qt::UserRole + 1, DoneRole };

    using QAbstractListModel::QAbstractListModel;

    int rowCount(const QModelIndex &parent = QModelIndex()) const override;
    QVariant data(const QModelIndex &index, int role) const override;
    QHash<int, QByteArray> roleNames() const override;

    Q_INVOKABLE void addTask(const QString &title);

private:
    QList<Task> tasks_;
};

#include "tasklistmodel.h"

int TaskListModel::rowCount(const QModelIndex &) const
{
    return tasks_.size();
}

QVariant TaskListModel::data(const QModelIndex &index, int role) const
{
    const Task &task = tasks_[index.row()];
    if (role == TitleRole)
        return task.title;
    if (role == DoneRole)
        return task.done;
    return {};
}

QHash<int, QByteArray> TaskListModel::roleNames() const
{
    return {{TitleRole, "title"}};
}

void TaskListModel::addTask(const QString &title)
{
    tasks_.append({title, false});
}

