#include "tasklistmodel.h"

int TaskListModel::rowCount(const QModelIndex &parent) const
{
    if (parent.isValid())
        return 0;
    return static_cast<int>(tasks_.size());
}

QVariant TaskListModel::data(const QModelIndex &index, int role) const
{
    if (!checkIndex(index, CheckIndexOption::IndexIsValid | CheckIndexOption::ParentIsInvalid))
        return {};
    const Task &task = tasks_[index.row()];
    if (role == TitleRole)
        return task.title;
    if (role == DoneRole)
        return task.done;
    return {};
}

QHash<int, QByteArray> TaskListModel::roleNames() const
{
    return {{TitleRole, "title"}, {DoneRole, "done"}};
}

void TaskListModel::addTask(const QString &title)
{
    const int row = static_cast<int>(tasks_.size());
    beginInsertRows(QModelIndex(), row, row);
    tasks_.append({title, false});
    endInsertRows();
}

void TaskListModel::addTasks(const QList<Task> &tasks)
{
    if (tasks.isEmpty())
        return;
    const int first = static_cast<int>(tasks_.size());
    const int last = first + static_cast<int>(tasks.size());
    beginInsertRows(QModelIndex(), first, last);
    tasks_.append(tasks);
    endInsertRows();
}

void TaskListModel::toggleDone(int row)
{
    if (row < 0 || row >= rowCount())
        return;
    tasks_[row].done = !tasks_[row].done;
    const QModelIndex changed = index(row);
    emit dataChanged(changed, changed, {DoneRole});
}
